#include <algorithm>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

struct Student {
    string name;
    int marks;
};

class Roster {
public:
    void add(const string& name, int marks) {
        students_.push_back({name, marks});
    }

    double average() const {
        double total = 0;
        for (const Student& s : students_) {
            total += s.marks;
        }
        return students_.empty() ? 0 : total / students_.size();
    }

    void print_ranking() const {
        vector<Student> copy = students_;
        sort(copy.begin(), copy.end(), [](const Student& a, const Student& b) { return a.marks > b.marks; });
        for (const Student& s : copy) {
            cout << s.name << " " << s.marks << endl;
        }
    }

private:
    vector<Student> students_;
};

int main() {
    Roster r;
    r.add("Ravi", 78);
    r.add("Asha", 91);
    r.add("Mia", 85);
    r.print_ranking();
    cout << fixed << setprecision(1) << r.average() << endl;
    return 0;
}

#include <algorithm>
#include <iostream>
#include <optional>
#include <string>
#include <vector>
using namespace std;

struct Student {
    string name;
    int marks;
};

class Roster {
public:
    void add(const string& name, int marks) {
        students_.push_back({name, marks});
    }

    optional<Student> best() const {
        if (students_.empty()) {
            return nullopt;
        }
        return *max_element(students_.begin(), students_.end(),
                            [](const Student& a, const Student& b) { return a.marks < b.marks; });
    }

private:
    vector<Student> students_;
};

int main() {
    Roster r;
    auto none = r.best();
    cout << none.has_value() << endl;
    r.add("Ravi", 78);
    r.add("Asha", 91);
    auto top = r.best();
    if (top) {
        cout << top->name << " " << top->marks << endl;
    }
    return 0;
}

